/** Run once on an empty SQLite database. Enable foreign_keys on EVERY connection.
 * JSON columns hold preferences/practical details; API validates JSON shape.
 * IDs, UTC timestamps and invite token hashes are generated by the backend.
 */
export const schemaSql = `
PRAGMA foreign_keys = ON;
CREATE TABLE trips (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, destination TEXT NOT NULL,
 start_date TEXT NOT NULL, end_date TEXT NOT NULL CHECK(end_date >= start_date),
 base_area TEXT, transport TEXT, budget TEXT, preferences_json TEXT NOT NULL DEFAULT '{}',
 plan_revision INTEGER NOT NULL DEFAULT 0 CHECK(plan_revision >= 0), created_at TEXT NOT NULL
);
CREATE TABLE members (
 id TEXT PRIMARY KEY, trip_id TEXT NOT NULL REFERENCES trips(id),
 subject_id TEXT NOT NULL, display_name TEXT NOT NULL,
 preferences_json TEXT NOT NULL DEFAULT '{}', firm_limits_json TEXT NOT NULL DEFAULT '{}',
 UNIQUE(trip_id, subject_id), UNIQUE(trip_id, id)
);
CREATE TABLE invites (
 token_hash TEXT PRIMARY KEY, trip_id TEXT NOT NULL REFERENCES trips(id),
 expires_at TEXT NOT NULL, revoked_at TEXT
);
CREATE TABLE imports (
 id TEXT PRIMARY KEY, trip_id TEXT NOT NULL REFERENCES trips(id), normalized_url TEXT NOT NULL,
 status TEXT NOT NULL CHECK(status IN ('queued','processing','ready','partially_ready','needs_confirmation','failed')),
 thumbnail_url TEXT, error_code TEXT, created_at TEXT NOT NULL, UNIQUE(trip_id, normalized_url), UNIQUE(trip_id, id)
);
CREATE TABLE import_contributors (
 trip_id TEXT NOT NULL, import_id TEXT NOT NULL, member_id TEXT NOT NULL,
 PRIMARY KEY(import_id, member_id),
 FOREIGN KEY(trip_id, import_id) REFERENCES imports(trip_id, id),
 FOREIGN KEY(trip_id, member_id) REFERENCES members(trip_id, id)
);
CREATE TABLE places (
 id TEXT PRIMARY KEY, trip_id TEXT NOT NULL REFERENCES trips(id), name TEXT NOT NULL,
 identity_key TEXT NOT NULL, match_status TEXT NOT NULL CHECK(match_status IN ('confirmed','uncertain')),
 area TEXT, latitude REAL CHECK(latitude BETWEEN -90 AND 90), longitude REAL CHECK(longitude BETWEEN -180 AND 180),
 brief TEXT, practical_json TEXT NOT NULL DEFAULT '{}', UNIQUE(trip_id, identity_key), UNIQUE(trip_id, id),
 CHECK((latitude IS NULL) = (longitude IS NULL))
);
CREATE TABLE import_places (
 trip_id TEXT NOT NULL, import_id TEXT NOT NULL, place_id TEXT NOT NULL,
 PRIMARY KEY(import_id, place_id),
 FOREIGN KEY(trip_id, import_id) REFERENCES imports(trip_id, id),
 FOREIGN KEY(trip_id, place_id) REFERENCES places(trip_id, id)
);
CREATE TABLE evidence (
 id TEXT PRIMARY KEY, trip_id TEXT NOT NULL, place_id TEXT NOT NULL,
 source_url TEXT NOT NULL, retrieved_at TEXT NOT NULL, facts_json TEXT NOT NULL,
 FOREIGN KEY(trip_id, place_id) REFERENCES places(trip_id, id)
);
CREATE TABLE recommendations (
 trip_id TEXT NOT NULL, place_id TEXT PRIMARY KEY,
 verdict TEXT NOT NULL CHECK(verdict IN ('strong_match','recommended','mixed_fit','not_recommended','needs_more_information')),
 score INTEGER NOT NULL CHECK(score BETWEEN 0 AND 100), headline TEXT NOT NULL, text TEXT NOT NULL,
 evidence_status TEXT NOT NULL CHECK(evidence_status IN ('confirmed','partial','uncertain')),
 generated_at TEXT NOT NULL,
 FOREIGN KEY(trip_id, place_id) REFERENCES places(trip_id, id)
);
CREATE TABLE member_place_evaluations (
 trip_id TEXT NOT NULL, place_id TEXT NOT NULL, member_id TEXT NOT NULL,
 fit TEXT NOT NULL CHECK(fit IN ('strong','good','mixed','poor','blocked','insufficient_information')),
 matched_criteria_json TEXT NOT NULL DEFAULT '[]', conflicts_json TEXT NOT NULL DEFAULT '[]',
 PRIMARY KEY(place_id, member_id),
 FOREIGN KEY(trip_id, place_id) REFERENCES places(trip_id, id),
 FOREIGN KEY(trip_id, member_id) REFERENCES members(trip_id, id)
);
CREATE TABLE reactions (
 trip_id TEXT NOT NULL, place_id TEXT NOT NULL, member_id TEXT NOT NULL,
 value TEXT NOT NULL CHECK(value IN ('interested','pass')), PRIMARY KEY(place_id, member_id),
 FOREIGN KEY(trip_id, place_id) REFERENCES places(trip_id, id),
 FOREIGN KEY(trip_id, member_id) REFERENCES members(trip_id, id)
);
CREATE TABLE concerns (
 id TEXT PRIMARY KEY, trip_id TEXT NOT NULL, place_id TEXT NOT NULL, member_id TEXT NOT NULL,
 kind TEXT NOT NULL CHECK(kind IN ('price','distance','effort')), note TEXT,
 FOREIGN KEY(trip_id, place_id) REFERENCES places(trip_id, id),
 FOREIGN KEY(trip_id, member_id) REFERENCES members(trip_id, id)
);
CREATE TABLE day_assignments (
 trip_id TEXT NOT NULL, place_id TEXT PRIMARY KEY, date TEXT, position INTEGER NOT NULL CHECK(position >= 0),
 manual INTEGER NOT NULL CHECK(manual IN (0,1)), reason TEXT NOT NULL,
 FOREIGN KEY(trip_id, place_id) REFERENCES places(trip_id, id)
);
CREATE UNIQUE INDEX assignment_slot ON day_assignments(trip_id, ifnull(date, ''), position);
`;
